export function MISSION_DRAFT_V1(answers) {
  const team = answers.teamName || 'the team';
  return {
    statement: `${team} exists to discover, test and scale digital and AI-driven ways of working across the airline — turning promising ideas into working prototypes fast, and proving their value with real data before the business commits.`,
    objectives: [OBJECTIVE_PROTOTYPES, OBJECTIVE_PLATFORM, OBJECTIVE_SPEED, OBJECTIVE_SKILLS],
  };
}

export function MISSION_DRAFT_V2(answers) {
  const team = answers.teamName || 'the team';
  return {
    statement: `${team} exists to discover, test and scale digital and AI-driven ways of working across the airline — turning promising ideas into working prototypes fast, proving their value with real data, and building an ecosystem of external and university partnerships that keeps new thinking flowing in.`,
    objectives: [
      OBJECTIVE_PROTOTYPES,
      OBJECTIVE_PARTNERSHIPS,
      OBJECTIVE_PLATFORM,
      OBJECTIVE_SPEED,
      OBJECTIVE_IP,
    ],
  };
}

