export function buildMissionResult(answers) {
  const version = Number(answers.missionAccepted) === 2 ? 2 : 1;
  const draft = version === 2 ? MISSION_DRAFT_V2(answers) : MISSION_DRAFT_V1(answers);
  return {
    teamName: answers.teamName || 'Your Team',
    statement: draft.statement,
    objectives: draft.objectives,
    constraints: CANNED_CONSTRAINTS,
    userContext: answers.purpose || '',
    acceptedVersion: version,
  };
}

export function buildTargetOrg(answers) {
  return Number(answers.orgAccepted) === 2 ? TARGET_ORG_V2 : TARGET_ORG_V1;
}

export function computeTeamFit(targetOrg) {
  if (!targetOrg || !Array.isArray(targetOrg)) return null;
  // All target org roles start as gaps until team members are drag-assigned in TeamFitScreen
  const rows = targetOrg.map((role) => ({
    role,
    status: 'gap',
    assigned: [],
  }));
  return {
    rows,
    unplaced: [],
    summary: {
      total: rows.length,
      filled: 0,
      partial: 0,
      gaps: rows.length,
    },
  };
}
